script:
(function () {
  'use strict';
  // Taxable vs. tax-deferred (traditional) vs. tax-free (Roth), starting from the same pre-tax dollars.
  //   Traditional: the full pre-tax amount goes in, grows at r, and is taxed at the withdrawal rate.
  //   Roth: the pre-tax amount is taxed now (x (1 - tax now)), grows at r and comes out tax-free.
  //   Taxable: taxed now like Roth, and its earnings are taxed every year, so it grows at
  //   r x (1 - earnings tax rate); there is no further tax when it is withdrawn (basis = balance).
  //   Contributions are added at the end of each year; the starting amount is invested today.
  //   Income phase: level end-of-year withdrawals that use up each balance over the chosen years,
  //   PMT = B x i / (1 - (1 + i)^-n) (B / n at 0%); traditional income is then taxed at the withdrawal
  //   rate and the taxable account keeps growing at its after-tax rate.
  // Checked in Node (aq5/tests/tw.test.js): $10,000 once, 6%, 25 years, 24% now / 22% later:
  // traditional = 10,000 x 1.06^25 x 0.78 = $33,476.59, Roth = 7,600 x 1.06^25 = $32,618.22,
  // taxable at 15% earnings tax = 7,600 x 1.051^25 = $26,356.12; traditional = Roth exactly when the
  // two tax rates are equal; $6,000/yr end-of-year for 10 years at 6% = 6,000 x 13.180795 = $79,084.77;
  // PMT of $100,000 over 20 years at 5% = $8,024.26; 0% return gives B / n.
  // Federal rate reference shown in the form: the seven 2026 rates 10, 12, 22, 24, 32, 35, 37% (Rev.
  // Proc. 2025-32, checked) and long-term capital gains rates 0, 15, 20%.

  // --- calc start
  function grow(start, yearly, rate, years) {
    var bal = start, rows = [];
    for (var y = 1; y <= years; y++) {
      bal = bal * (1 + rate) + yearly;
      rows.push(bal);
    }
    return rows;
  }
  function payment(balance, rate, n) {
    if (n <= 0 || balance <= 0) return 0;
    if (Math.abs(rate) < 1e-12) return balance / n;
    return balance * rate / (1 - Math.pow(1 + rate, -n));
  }
  function compare(o) {
    var afterNow = 1 - o.taxNow, taxableRate = o.rate * (1 - o.earnTax);
    var trad = grow(o.start, o.yearly, o.rate, o.years);
    var roth = grow(o.start * afterNow, o.yearly * afterNow, o.rate, o.years);
    var taxable = grow(o.start * afterNow, o.yearly * afterNow, taxableRate, o.years);
    var tradEnd = trad[o.years - 1], rothEnd = roth[o.years - 1], taxEnd = taxable[o.years - 1];
    var wTaxableRate = o.wRate * (1 - o.earnTax);
    return {
      trad: trad, roth: roth, taxable: taxable,
      tradAfter: tradEnd * (1 - o.taxLater), rothAfter: rothEnd, taxableAfter: taxEnd,
      tradTaxDue: tradEnd * o.taxLater,
      invested: o.start + o.yearly * o.years,
      upfrontTax: (o.start + o.yearly * o.years) * o.taxNow,
      tradIncome: payment(tradEnd, o.wRate, o.wYears) * (1 - o.taxLater),
      rothIncome: payment(rothEnd, o.wRate, o.wYears),
      taxableIncome: payment(taxEnd, wTaxableRate, o.wYears)
    };
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var OUTPUTS = ['twBest', 'twTradAfter', 'twRothAfter', 'twTaxableAfter', 'twTradIncome', 'twRothIncome',
                 'twTaxableIncome', 'twTradBal', 'twRothBal', 'twTaxableBal', 'twTradTax', 'twUpfront',
                 'twTradIn', 'twRothIn', 'twTaxableIn', 'twIncomeYears'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function fail(msg) {
    var error = document.getElementById('twError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { set(id, '–'); });
    document.getElementById('twSchedule').innerHTML = '';
    document.getElementById('twNote').hidden = true;
  }

  function update() {
    document.getElementById('twError').hidden = true;
    var o = {
      start: num('twStart'), yearly: num('twYearly'), years: Math.round(num('twYears')), rate: num('twRate') / 100,
      taxNow: num('twTaxNow') / 100, taxLater: num('twTaxLater') / 100, earnTax: num('twEarnTax') / 100,
      wYears: Math.round(num('twWYears')), wRate: num('twWRate') / 100
    };
    if ([o.start, o.yearly, o.years, o.rate, o.taxNow, o.taxLater, o.earnTax, o.wYears, o.wRate].some(isNaN)) {
      return fail('Fill in every box with a number.');
    }
    if (o.start < 0 || o.yearly < 0 || o.start + o.yearly <= 0) return fail('Enter a non-negative starting amount and yearly amount (not both zero).');
    if (o.years < 1 || o.years > 60) return fail('Enter 1 to 60 years of investing.');
    if (o.rate < 0 || o.rate > 0.3 || o.wRate < 0 || o.wRate > 0.3) return fail('Enter returns from 0% to 30%.');
    if ([o.taxNow, o.taxLater, o.earnTax].some(function (t) { return t < 0 || t > 0.7; })) return fail('Enter tax rates from 0% to 70%.');
    if (o.wYears < 1 || o.wYears > 50) return fail('Enter 1 to 50 years of withdrawals.');

    var r = compare(o);
    var afterNow = 1 - o.taxNow;
    var options = [
      { name: 'Tax-deferred (traditional)', value: r.tradAfter },
      { name: 'Tax-free (Roth)', value: r.rothAfter },
      { name: 'Taxable', value: r.taxableAfter }
    ].sort(function (a, b) { return b.value - a.value; });
    var tie = Math.abs(options[0].value - options[1].value) < 0.5;
    set('twBest', tie ? options[0].name.split(' (')[0] + ' and ' + options[1].name.split(' (')[0].toLowerCase() + ' tie' : options[0].name);
    set('twTradAfter', money.format(r.tradAfter));
    set('twRothAfter', money.format(r.rothAfter));
    set('twTaxableAfter', money.format(r.taxableAfter));
    set('twTradIn', money.format(r.invested));
    set('twRothIn', money.format(r.invested * afterNow));
    set('twTaxableIn', money.format(r.invested * afterNow));
    set('twTradBal', money.format(r.trad[o.years - 1]));
    set('twRothBal', money.format(r.roth[o.years - 1]));
    set('twTaxableBal', money.format(r.taxable[o.years - 1]));
    set('twTradTax', money.format(r.tradTaxDue));
    set('twUpfront', money.format(r.upfrontTax));
    set('twTradIncome', money.format(r.tradIncome));
    set('twRothIncome', money.format(r.rothIncome));
    set('twTaxableIncome', money.format(r.taxableIncome));
    set('twIncomeYears', 'Yearly after-tax income for ' + o.wYears + (o.wYears === 1 ? ' year' : ' years'));

    var note = document.getElementById('twNote'), pctNow = Math.round(o.taxNow * 1000) / 10;
    note.hidden = false;
    note.textContent = 'With the same pre-tax dollars, traditional and Roth come out exactly equal when the tax rate on ' +
      'withdrawals equals the rate now (' + pctNow + '%). A lower rate later favors traditional, a higher one favors Roth. ' +
      'With positive returns, the taxable account trails Roth because its earnings are taxed along the way.';

    var rows = [];
    for (var y = 1; y <= o.years; y++) {
      rows.push('<tr><td>' + y + '</td><td>' + money.format(r.trad[y - 1]) + '</td><td>' +
        money.format(r.trad[y - 1] * (1 - o.taxLater)) + '</td><td>' + money.format(r.roth[y - 1]) + '</td><td>' +
        money.format(r.taxable[y - 1]) + '</td></tr>');
    }
    document.getElementById('twSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('twForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
